/* @lc app=leetcode id=2132 lang=kotlin */ class Solution { fun possibleToStamp(M: Array<IntArray>, h: Int, w: Int): Boolean = M.size.let { n -> M[0].size.let { m -> Array(n + 1) { IntArray(m + 1) }.apply { (0 until n).forEach { i -> (0 until m).forEach { j -> (this[i][j + 1] + this[i + 1][j] - this[i][j] + M[i][j]).also { this[i + 1][j + 1] = it } } } }.let { pref -> Array(n + 1) { IntArray(m + 1) }.apply { (h..n).forEach { i -> (w..m).forEach { j -> if (pref[i][j] - pref[i - h][j] - pref[i][j - w] + pref[i - h][j - w] == 0) this[i][j] = 1 } } }.let { can -> Array(n + 1) { IntArray(m + 1) }.apply { (0 until n).forEach { i -> (0 until m).forEach { j -> (this[i][j + 1] + this[i + 1][j] - this[i][j] + can[i + 1][j + 1]).also { this[i + 1][j + 1] = it } } } }.let { prefCan -> (0 until n).all { i -> (0 until m).all { j -> M[i][j] == 1 || (prefCan[minOf(i + h, n)][minOf(j + w, m)] - prefCan[i][minOf(j + w, m)] - prefCan[minOf(i + h, n)][j] + prefCan[i][j]) > 0 } } } } } } } }